const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
let W=innerWidth,H=innerHeight,DPR=1,now=0,last=0,gameOn=false,toastTimer,attackFx=0,skillCd=0,worldMinutes=494;
function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,2);canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
const saved=(()=>{try{return JSON.parse(localStorage.satisfySave||'{}')}catch{return {}}})();
const state={x:saved.x||480,y:saved.y||490,face:1,hp:saved.hp||100,maxHp:100,level:saved.level||1,xp:saved.xp||0,gold:saved.gold||42,kills:saved.kills||0,slimeKills:saved.slimeKills||0,quest:saved.quest||false,questDone:saved.questDone||false,items:saved.items||[{name:'Apprentice Sword',icon:'⚔',desc:'A plain sword · Normal',count:1},{name:'Travel Rations',icon:'◈',desc:'Restores a little stamina',count:3},{name:'Iron Ore',icon:'⬟',desc:'A common smithing material',count:2}],invOpen:false,dialogOpen:false,stun:0,attack:0,potion:2};
const enemies=[];for(let i=0;i<8;i++)enemies.push({x:790+i*176+(i%2)*30,y:410+(i%3)*93,hp:3,max:3,alive:true,hit:0,attack:0,seed:i});
const decorations=[];let seed=17;function rand(){seed=(seed*9301+49297)%233280;return seed/233280}for(let i=0;i<260;i++)decorations.push({x:rand()*2500,y:rand()*1050,t:rand(),s:.5+rand()*1.1});
const obstacles=[{x:265,y:310,w:165,h:120,type:'house'},{x:85,y:180,w:126,h:98,type:'house'},{x:60,y:420,w:132,h:92,type:'house'},{x:344,y:155,w:112,h:94,type:'smith'},{x:508,y:278,w:90,h:76,type:'house'}];
function save(){try{localStorage.satisfySave=JSON.stringify({...state,invOpen:false,dialogOpen:false})}catch{}}
function worldToScreen(x,y,cx,cy){return [x-cx+W/2,y-cy+H/2]}
function path(points,fill,stroke,width=1){ctx.beginPath();ctx.moveTo(...points[0]);for(let i=1;i<points.length;i++)ctx.lineTo(...points[i]);ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke()}}
function drawGround(cx,cy){ctx.fillStyle='#566751';ctx.fillRect(0,0,W,H);const ox=-((cx-W/2)%96),oy=-((cy-H/2)%96);for(let x=ox-96;x<W+96;x+=96)for(let y=oy-96;y<H+96;y+=96){let k=Math.sin((x+cx)*.013+(y+cy)*.017);ctx.fillStyle=k>.65?'#5c7058':k<-.7?'#52644f':'#586a53';ctx.fillRect(x,y,98,98)}
// meandering road to Winston
ctx.save();ctx.translate(W/2-cx,H/2-cy);ctx.beginPath();ctx.moveTo(-100,560);ctx.bezierCurveTo(170,550,180,450,425,453);ctx.bezierCurveTo(620,457,655,565,865,550);ctx.bezierCurveTo(1080,535,1140,405,1370,405);ctx.bezierCurveTo(1560,406,1740,490,2050,450);ctx.lineWidth=102;ctx.strokeStyle='#7b7659';ctx.stroke();ctx.lineWidth=89;ctx.strokeStyle='#9a8d69';ctx.stroke();ctx.lineWidth=2;ctx.setLineDash([12,20]);ctx.strokeStyle='#b9a67c66';ctx.stroke();ctx.setLineDash([]);ctx.restore();
ctx.save();for(const d of decorations){let [x,y]=worldToScreen(d.x,d.y,cx,cy);if(x<-30||x>W+30||y<-30||y>H+30)continue;let r=d.s*7;if(d.t<.15){ctx.fillStyle='#394e3d';ctx.beginPath();ctx.ellipse(x,y,r*1.35,r*.7,.25,0,7);ctx.fill();ctx.fillStyle='#788363';ctx.beginPath();ctx.ellipse(x-r*.4,y-r*.25,r*.35,r*.23,0,0,7);ctx.fill()}else if(d.t<.33){ctx.strokeStyle='#c1bd8b';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-r*.2,y-r);ctx.moveTo(x,y);ctx.lineTo(x+r*.6,y-r*.55);ctx.stroke();ctx.fillStyle='#d2be86';ctx.fillRect(x-r*.3,y-r*.9,2,2)}else if(d.t<.39){ctx.fillStyle='#b9a27a';ctx.beginPath();ctx.ellipse(x,y,r,r*.58,.2,0,7);ctx.fill()}else{ctx.fillStyle='#b8a874';ctx.beginPath();ctx.arc(x,y,1.3,0,7);ctx.fill()}}ctx.restore();
}
function drawTree(x,y,s,cx,cy){let [sx,sy]=worldToScreen(x,y,cx,cy);if(sx<-100||sx>W+100||sy<-100||sy>H+100)return;ctx.fillStyle='#342e25';ctx.fillRect(sx-3,sy-7,6,16);ctx.fillStyle='#263a2d';ctx.beginPath();ctx.arc(sx,sy-15,17*s,0,7);ctx.fill();ctx.fillStyle='#3b523b';ctx.beginPath();ctx.arc(sx-8*s,sy-20*s,10*s,0,7);ctx.fill();ctx.fillStyle='#657150';ctx.beginPath();ctx.arc(sx-5*s,sy-24*s,4*s,0,7);ctx.fill()}
function drawBuilding(o,cx,cy){let [x,y]=worldToScreen(o.x,o.y,cx,cy),w=o.w,h=o.h;if(x<-250||x>W+250)return;ctx.fillStyle='#25302a';ctx.fillRect(x+10,y+h-5,w-5,17);ctx.fillStyle='#b7a17b';ctx.fillRect(x,y+24,w,h-24);ctx.fillStyle=o.type==='smith'?'#51443a':'#6d5645';path([[x-12,y+30],[x+w/2,y-13],[x+w+12,y+30]],'#443a32','#b79b70',2);ctx.fillStyle='#3a342c';ctx.fillRect(x+12,y+39,19,23);ctx.fillRect(x+w-34,y+39,19,23);ctx.fillStyle='#9e8d66';ctx.fillRect(x+13,y+40,17,21);ctx.fillRect(x+w-33,y+40,17,21);ctx.strokeStyle='#51473a';ctx.beginPath();ctx.moveTo(x+21,y+40);ctx.lineTo(x+21,y+61);ctx.moveTo(x+13,y+50);ctx.lineTo(x+30,y+50);ctx.stroke();ctx.fillStyle='#47362b';ctx.fillRect(x+w/2-13,y+h-39,26,39);ctx.fillStyle='#c2ab77';ctx.fillRect(x+w/2-2,y+h-18,3,3);if(o.type==='smith'){ctx.fillStyle='#c47c4c';ctx.beginPath();ctx.arc(x+w-18,y+15,6+Math.sin(now*3)*1.5,0,7);ctx.fill();ctx.fillStyle='#d8b576';ctx.font='9px monospace';ctx.fillText('K H A N ’ S   F O R G E',x-4,y-22)}}
function drawKhan(cx,cy){let [x,y]=worldToScreen(405,390,cx,cy);person(x,y,'#bbaa82','Khan',true)}
function person(x,y,color,name,npc=false){ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(x,y+8,12,5,0,0,7);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,8,12,0,0,7);ctx.fill();ctx.fillStyle='#d7b995';ctx.beginPath();ctx.arc(x,y-11,6,0,7);ctx.fill();ctx.fillStyle=npc?'#8b8064':'#313c37';ctx.fillRect(x-8,y+1,16,6);ctx.textAlign='center';ctx.font='10px Manrope';ctx.fillStyle=npc?'#e4d7ae':'#b8e4a0';ctx.fillText(name,x,y-25);ctx.textAlign='left'}
function drawEnemy(e,cx,cy){if(!e.alive)return;let [x,y]=worldToScreen(e.x,e.y,cx,cy),bob=Math.sin(now*4+e.seed)*2;ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(x,y+9,16,6,0,0,7);ctx.fill();ctx.fillStyle=e.hit?'#f5c995':'#81a56d';ctx.beginPath();ctx.ellipse(x,y+bob,15,12,0,0,7);ctx.fill();ctx.fillStyle='#a1bd7f';ctx.beginPath();ctx.ellipse(x-4,y-4+bob,7,5,-.4,0,7);ctx.fill();ctx.fillStyle='#e7e4c4';ctx.beginPath();ctx.arc(x-5,y+bob,1.6,0,7);ctx.arc(x+5,y+bob,1.6,0,7);ctx.fill();ctx.fillStyle='#1f2c24';ctx.beginPath();ctx.arc(x-5,y+bob,0.7,0,7);ctx.arc(x+5,y+bob,0.7,0,7);ctx.fill();if(e.hp<e.max){ctx.fillStyle='#20251f';ctx.fillRect(x-14,y-22,28,3);ctx.fillStyle='#ca6754';ctx.fillRect(x-14,y-22,28*e.hp/e.max,3)}ctx.textAlign='center';ctx.font='9px Manrope';ctx.fillStyle='#aee19c';ctx.fillText('Field Slime',x,y-28);ctx.textAlign='left'}

function drawPlayer(cx,cy){let [x,y]=worldToScreen(state.x,state.y,cx,cy),moving=keys.size>0||touchDirs.size>0,bob=moving?Math.sin(now*13)*2:Math.sin(now*2)*.7;ctx.save();ctx.translate(x,y+bob);ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(0,9,13,6,0,0,7);ctx.fill();ctx.fillStyle='#273a36';ctx.beginPath();ctx.moveTo(-8,-9);ctx.lineTo(8,-9);ctx.lineTo(11,7);ctx.lineTo(-11,7);ctx.closePath();ctx.fill();ctx.fillStyle='#b9a875';ctx.fillRect(-8,2,16,4);ctx.fillStyle='#c7a582';ctx.beginPath();ctx.arc(0,-14,7,0,7);ctx.fill();ctx.fillStyle='#473e34';ctx.beginPath();ctx.arc(0,-17,7,Math.PI,0);ctx.fill();ctx.fillStyle='#d3c7a7';ctx.fillRect(-5,-1,10,3);ctx.strokeStyle='#c8c0a0';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(state.face*7,-5);ctx.lineTo(state.face*13,-11);ctx.stroke();ctx.strokeStyle='#e2d6ae';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(state.face*13,-11);ctx.lineTo(state.face*15,-16);ctx.stroke();if(state.attack>0||attackFx>0){let a=(state.attack||attackFx);ctx.globalAlpha=Math.min(1,a*2);ctx.strokeStyle='#f0daa0';ctx.lineWidth=3;ctx.beginPath();ctx.arc(state.face*5,-3,25,-.9,1.1);ctx.stroke()}ctx.restore();ctx.textAlign='center';ctx.font='10px Manrope';ctx.fillStyle='#d9e7bc';ctx.fillText('Wayfarer',x,y-34);ctx.textAlign='left'}
function drawWorld(){let camX=clamp(state.x, W/2,2500-W/2),camY=clamp(state.y,H/2,1050-H/2);drawGround(camX,camY);ctx.save();ctx.translate(W/2-camX,H/2-camY); // landmarks
// distant hills
for(let i=0;i<8;i++){let x=i*360-140;ctx.fillStyle=i%2?'#475d4c':'#4b604f';ctx.beginPath();ctx.ellipse(x,70,260,90,0,Math.PI,Math.PI*2);ctx.fill();}
ctx.restore();for(let i=0;i<obstacles.length;i++)drawBuilding(obstacles[i],camX,camY);
// trees along the settled edge
for(let i=0;i<22;i++){let x=160+i*104,y=100+(i%4)*94;drawTree(x,y,1+(i%3)*.14,camX,camY)}
for(const e of enemies)drawEnemy(e,camX,camY);drawKhan(camX,camY);drawPlayer(camX,camY);
// atmosphere motes
for(let i=0;i<12;i++){let x=(i*173+now*4)%W,y=(i*97+Math.sin(now+i)*18+H*.22)%H;ctx.fillStyle='#e5d8a933';ctx.beginPath();ctx.arc(x,y,1.2,0,7);ctx.fill()}}
function setToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2400)}
function feed(text){let f=$('#feed'),d=document.createElement('div');d.textContent='› '+text;f.prepend(d);while(f.children.length>4)f.lastChild.remove()}
function updateHud(){const pct=100*state.hp/state.maxHp;$('#hpBar').style.width=pct+'%';$('#hpText').textContent=`${Math.ceil(state.hp)} / ${state.maxHp}`;$('#xpBar').style.width=(state.xp%100)+'%';$('#xpText').textContent=`${state.xp%100} / 100 XP`;$('#level').textContent='LV. '+state.level;$('#gold').textContent=state.gold;$('#str').textContent=10+(state.level-1)*2;$('#sta').textContent=10+(state.level-1);$('#weight').textContent=(12+state.items.reduce((a,i)=>a+i.count,0)*2)+' / 100';$('#questCount').textContent=`${Math.min(state.slimeKills,3)} / 3`;$('#inventoryWeight').textContent=$('#weight').textContent;$('#inventoryLevel').textContent=state.level;$('#questTitle').textContent=state.questDone?'A Smith’s Gratitude':state.quest?'A Smith’s Request':'A Smith’s Request';$('#questDesc').textContent=state.questDone?'Khan’s commission is complete. Winston remembers a helping hand.':'Khan needs the fields cleared before he can finish his latest commission.';$('#objective').textContent=state.questDone?'Return to Khan':'Slimes defeated';$('#objectiveDot').textContent=state.questDone?'✓':'◌';$('#questCount').textContent=state.questDone?'COMPLETE':`${Math.min(state.slimeKills,3)} / 3`;updateItems();save()}
function updateItems(){let box=$('#itemsList');if(!box)return;box.innerHTML='';for(const it of state.items){let row=document.createElement('div');row.className='item';row.innerHTML=`<div class="item-icon">${it.icon}</div><div class="item-info"><b>${it.name}</b><small>${it.desc}</small></div><div class="item-count">× ${it.count}</div>`;box.append(row)}}
function updateClock(dt){worldMinutes+=dt*3;let mins=Math.floor(worldMinutes)%1440;$('#clock').textContent=String(Math.floor(mins/60)).padStart(2,'0')+':'+String(mins%60).padStart(2,'0')}
const keys=new Set(),touchDirs=new Set();function loop(ts){let dt=Math.min(.04,(ts-last)/1000||0);last=ts;now=ts/1000;if(gameOn){updateClock(dt);tick(dt)}drawWorld();requestAnimationFrame(loop)}requestAnimationFrame(loop);

function tick(dt){if(state.dialogOpen||state.invOpen)return;let dx=0,dy=0;if(keys.has('KeyW')||keys.has('ArrowUp'))dy--;if(keys.has('KeyS')||keys.has('ArrowDown'))dy++;if(keys.has('KeyA')||keys.has('ArrowLeft'))dx--;if(keys.has('KeyD')||keys.has('ArrowRight'))dx++;for(const d of touchDirs){if(d==='up')dy--;if(d==='down')dy++;if(d==='left')dx--;if(d==='right')dx++}if(dx||dy){let len=Math.hypot(dx,dy);dx/=len;dy/=len;state.x=clamp(state.x+dx*175*dt,35,2450);state.y=clamp(state.y+dy*175*dt,95,1010);if(dx)state.face=Math.sign(dx)}state.stun=Math.max(0,state.stun-dt);state.attack=Math.max(0,state.attack-dt*3);attackFx=Math.max(0,attackFx-dt*2);skillCd=Math.max(0,skillCd-dt);for(const e of enemies){if(!e.alive)continue;e.hit=Math.max(0,e.hit-dt);e.attack+=dt;let dist=Math.hypot(state.x-e.x,state.y-e.y);if(dist<175&&dist>29){e.x+=((state.x-e.x)/dist)*18*dt;e.y+=((state.y-e.y)/dist)*18*dt}if(dist<37&&e.attack>1.3){e.attack=0;state.hp=Math.max(0,state.hp-7);feed('A Field Slime hits you for 7 damage.');if(state.hp<=0)respawn()}}if(Math.random()<dt*.24)updateHud();checkInteraction()}
function respawn(){state.hp=state.maxHp;state.x=480;state.y=490;feed('You returned to Winston. No experience was lost.');setToast('Returned to Winston · Beginner protection applied');updateHud()}
function nearestEnemy(range=68){let best=null,bd=range;for(const e of enemies){let d=Math.hypot(state.x-e.x,state.y-e.y);if(e.alive&&d<bd){bd=d;best=e}}return best}
function hitEnemy(power=1,range=72){let target=nearestEnemy(range);if(!target){setToast('No target in range');return}target.hp-=power;target.hit=.22;target.attack=0;state.attack=.25;attackFx=.8;state.face=target.x>=state.x?1:-1;feed(power>1?'Rising Cut deals a critical 2 damage!':'Strike connects · 1 damage');if(target.hp<=0){target.alive=false;state.kills++;state.slimeKills++;state.xp+=24;state.gold+=2;feed('Field Slime defeated · +24 XP · +2 G');if(state.quest&&state.slimeKills>=3&&!state.questDone)setToast('Quest objective complete · Return to Khan');checkLevel();updateHud()} }
function checkLevel(){while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.maxHp+=12;state.hp=state.maxHp;setToast(`Level up! You reached level ${state.level}`);feed(`Level ${state.level} attained · Stats increased`)}}
function attack(){if(!gameOn||state.dialogOpen)return;hitEnemy(1,72)}function skill(){if(!gameOn||state.dialogOpen)return;if(skillCd>0){setToast('Rising Cut is recharging');return}skillCd=4;hitEnemy(2,106);state.attack=.6;attackFx=1.2}
function potion(){if(state.potion<=0){setToast('No health tonics remaining');return}if(state.hp===state.maxHp){setToast('Health is already full');return}state.potion--;state.hp=Math.min(state.maxHp,state.hp+38);let it=state.items.find(i=>i.name==='Travel Rations');feed('Health tonic used · +38 health');setToast('Restored 38 health');updateHud()}
function closestPerson(){return Math.hypot(state.x-405,state.y-390)<95}
function checkInteraction(){let el=$('#interaction');if(!gameOn||state.dialogOpen||state.invOpen){el.classList.remove('show');return}if(closestPerson()){el.classList.add('show');$('#interactText').textContent=state.quest&&state.slimeKills>=3&&!state.questDone?'Report to Khan':state.quest?'Talk to Khan':'Speak with Khan'}else{el.classList.remove('show')}}
function openDialog(){if(!gameOn)return;if(closestPerson()){showKhan();return}let e=nearestEnemy(70);if(e){attack();return}setToast('No one nearby to speak with')}
function showDialog(kicker,title,body,options){$('#dialogKicker').textContent=kicker;$('#dialogTitle').textContent=title;$('#dialogBody').textContent=body;let box=$('#dialogOptions');box.innerHTML='';for(const [label,fn] of options){let b=document.createElement('button');b.textContent=label;b.onclick=fn;box.append(b)}$('#dialog').classList.add('open');state.dialogOpen=true}
function closeDialog(){$('#dialog').classList.remove('open');state.dialogOpen=false;checkInteraction()}
function showKhan(){if(state.quest&&state.slimeKills>=3&&!state.questDone){showDialog('WINSTON · SMITHY','Khan',"The field’s quiet again. Well done, friend. Take this—good work should be repaid. I’ll remember the way you handled yourself.",[['Accept reward · 80 XP · 12 G',()=>{state.questDone=true;state.gold+=12;state.xp+=80;feed('Quest complete · A Smith’s Request · +80 XP · +12 G');checkLevel();updateHud();setToast('Quest completed · Khan’s Gratitude');showKhan()}],['Ask about crafting',()=>showCraft()],['Leave',closeDialog]]);return}let body=state.questDone?'The forge is warm and the town is safer for your help. I have a little ironwork if you’d like to learn.':state.quest?'Keep your eyes open out there. Three slimes should do it. Then come tell me.':'Those slimes are spoiling the road east of town. Clear three of them and I’ll pay you for your trouble. No heroics needed—just stay on your feet.';let opts=state.quest?[['Ask about smithing',()=>showCraft()],['Leave',closeDialog]]:[['Accept quest · A Smith’s Request',()=>{state.quest=true;feed('Quest accepted · A Smith’s Request');setToast('Quest accepted · Slimes defeated 0 / 3');updateHud();closeDialog()}],['Ask about smithing',()=>showCraft()],['Not now',closeDialog]];showDialog('WINSTON · SMITHY', 'Khan',body,opts)}
function showCraft(){let enough=state.gold>=20&&state.items.some(i=>i.name==='Iron Ore'&&i.count>=2);let opts=enough?[['Forge Fieldsteel Blade · 2 Iron Ore · 20 G',()=>craftBlade()],['Back',()=>showKhan()]]:[['I need 2 Iron Ore and 20 G',()=>showKhan()],['Back',()=>showKhan()]];showDialog('CRAFTING · APPRENTICE METHOD','The Smithy',enough?'Khan can shape your ore into a sturdier blade. The result is not guaranteed to be beautiful, but it will be yours.':'Khan’s apprentice method needs 2 Iron Ore and 20 gold. Slimes sometimes drop ore, and the fields hold more.',opts)}
function craftBlade(){let ore=state.items.find(i=>i.name==='Iron Ore');ore.count-=2;state.gold-=20;if(!ore.count)state.items=state.items.filter(i=>i!==ore);state.items.push({name:'Fieldsteel Blade',icon:'⚔',desc:'Hand-forged by Khan · Normal',count:1});feed('Crafted Fieldsteel Blade · Creator: Khan');setToast('A new blade is yours');updateHud();showDialog('CRAFTING · SUCCESS','Fieldsteel Blade','Khan turns the finished blade in the light. “Not legendary,” he says, “but it’ll serve you better than a rusty edge.”',['Close'].map(x=>[x,closeDialog]))}

function enterWorld(){gameOn=true;$('#startScreen').classList.add('hidden');setToast('Welcome to Winston · The world is yours');feed('You have entered the northern fields.');updateHud()}
$('#enterButton').addEventListener('click',enterWorld);$('#closeDialog').addEventListener('click',closeDialog);$('#dialog').addEventListener('click',e=>{if(e.target.id==='dialog')closeDialog()});
function openInventory(){if(!gameOn)return;state.invOpen=true;$('#inventory').classList.add('open');updateItems()}function closeInventory(){state.invOpen=false;$('#inventory').classList.remove('open')}
$('#inventoryButton').addEventListener('click',openInventory);$('#closeInventory').addEventListener('click',closeInventory);$('#inventory').addEventListener('click',e=>{if(e.target.id==='inventory')closeInventory()});
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape'){if(state.dialogOpen)closeDialog();if(state.invOpen)closeInventory();return}if(e.code==='KeyE'){openDialog();return}if(e.code==='KeyI'){state.invOpen?closeInventory():openInventory();return}if(e.code==='Space'){attack();return}if(e.code==='Digit1'){attack();return}if(e.code==='Digit2'){skill();return}if(e.code==='Digit3'){potion();return}keys.add(e.code)});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();touchDirs.clear()});
document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{let action=b.dataset.action;if(action==='attack')attack();if(action==='skill')skill();if(action==='potion')potion();if(action==='interact')openDialog()}));
document.querySelectorAll('[data-dir]').forEach(b=>{let dir=b.dataset.dir;const down=e=>{e.preventDefault();touchDirs.add(dir);try{b.setPointerCapture(e.pointerId)}catch{}};const up=e=>{e.preventDefault();touchDirs.delete(dir)};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up)});
// Restore only durable progression; character always reappears in the peaceful outskirts.
updateHud();

